(()=>{function refreshDisposal(){const n=id=>Math.max(0,Number(document.getElementById(id).value)||0),base=Math.floor(n('calc-labs'))*Math.floor(n('calc-hplc-count'))*n('calc-flow')*60*n('calc-hours-day')*n('calc-days-week')*n('calc-weeks-year')/1000,disposal=base*n('calc-waste-reduction')/100*n('calc-disposal-cost'),material=base*n('calc-recovery')/100*n('calc-solvent-cost'),fmt=v=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(v);for(const [key,v] of [['disposal-saving',disposal],['combined-saving',disposal+material],['combined-three',3*(disposal+material)]])document.querySelectorAll('[data-'+key+']').forEach(e=>e.textContent=fmt(v));const chart=document.getElementById('cumulative-disposal');if(!chart)return;chart.innerHTML=[1,2,3].map(y=>'<div class="cum-col"><strong>'+fmt(disposal*y)+'</strong><div class="cum-track"><div class="cum-bar" style="height:'+(disposal?y/3*100:0)+'%"></div></div><span>'+y+(y===1?' year':' years')+'</span></div>').join('');chart.setAttribute('aria-label',[1,2,3].map(y=>y+' years: '+fmt(disposal*y)).join('; '));}document.addEventListener('resolve-model',refreshDisposal);refreshDisposal();})();